T024,Security review of AI infrastructure,Blocked,James Wong,High,Sprint 5,2026-05-26,Security,"Penetration testing and vulnerability assessment - BLOCKED: waiting for security team availability"
T025,Legal review of data usage,In Progress,Sarah Lin,High,Sprint 3,2026-04-28,Compliance,"Review data privacy compliance for using customer delivery data in ML models"`;

// ---------- Helpers ----------
function parseCsv(text) {
  const rows = [];
  let row = [], field = '', inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"' && text[i + 1] === '"') { field += '"'; i++; }
      else if (c === '"') inQuotes = false;
      else field += c;
    } else if (c === '"') inQuotes = true;
    else if (c === ',') { row.push(field); field = ''; }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && text[i + 1] === '\n') i++;
      row.push(field); field = '';
      if (row.some((v) => v.trim() !== '')) rows.push(row);
      row = [];
    } else field += c;
  }
  row.push(field);
  if (row.some((v) => v.trim() !== '')) rows.push(row);
  const [header, ...body] = rows;
  return body.map((r) => Object.fromEntries(header.map((h, i) => [h.trim(), (r[i] ?? '').trim()])));
}

const DAY = 86400000;
const toDate = (s) => { const [y, m, d] = s.split('-').map(Number); return new Date(Date.UTC(y, m - 1, d)); };
const fmt = (d) => d.toISOString().slice(0, 10);
const addDays = (d, n) => new Date(d.getTime() + n * DAY);
const daysBetween = (a, b) => Math.round((b - a) / DAY);
const countBy = (arr, key) => arr.reduce((acc, x) => ({ ...acc, [x[key]]: (acc[x[key]] ?? 0) + 1 }), {});

const asOf = toDate(cfg.asOfDate);
const projectStart = toDate(cfg.projectStartDate);
const upcomingEnd = addDays(asOf, Number(cfg.upcomingWindowDays));
const dueSoonEnd = addDays(asOf, Number(cfg.dueSoonDays));
const STATUSES = ['Done', 'In Progress', 'Blocked', 'To Do'];

// ---------- Timeline: week numbers -> calendar dates ----------
const timeline = parseCsv(TIMELINE_CSV).map((p) => {
  const start = addDays(projectStart, (Number(p.start_week) - 1) * 7);
  const end = addDays(projectStart, Number(p.end_week) * 7 - 1);
  const status = end < asOf ? 'Completed (by schedule)' : start > asOf ? 'Upcoming' : 'Current';
  return {
    phase: Number(p.phase),
    phase_name: p.phase_name,
    start_week: Number(p.start_week),
    end_week: Number(p.end_week),
    start_date: fmt(start),
    end_date: fmt(end),
    schedule_status: status,
    key_activities: p.key_activities.split(';').map((s) => s.trim()).filter(Boolean),
    milestones: p.milestones_deliverables.split(';').map((s) => s.trim()).filter(Boolean),
  };
});

// Each milestone is due at the end of its phase.
const milestones = timeline.flatMap((p) => p.milestones.map((m) => ({
  milestone: m,
  phase: p.phase,
  phase_name: p.phase_name,
  due_week: p.end_week,
  due_date: p.end_date,
  days_from_as_of: daysBetween(asOf, toDate(p.end_date)),
})));

// ---------- Project outcome phrases ----------
// Short verbatim phrases from the description (goals, use cases, capabilities). Agents cite these
// from a fixed list instead of free-text quoting, so a citation can never be invented.
const LEAD = /^(and|or|including|include|includes|the company aims to|aims to|by leveraging|by|to|of|with|is embarking on an ai adoption initiative to|key goals include|this project will focus on|beginning with|followed by|will)\s+/i;
const outcomePhrases = [...new Set(PROJECT_DESCRIPTION.split('\n').slice(1).join(' ')
  .split(/[.;,]|\s+and\s+(?=[a-z]+ing\b|improv|reduc|lower|minim|uncov|drive|enhanc)/)
  .map((s) => { let t = s.trim(), prev; do { prev = t; t = t.replace(LEAD, ''); } while (t !== prev); return t; })
  .filter((s) => { const n = s.split(/\s+/).length; return n >= 2 && n <= 9 && !/ABCDE|^This|^The /.test(s); }))];
const USE_CASES = ['demand forecasting', 'route optimization', 'inventory management', 'customer support']
  .filter((u) => PROJECT_DESCRIPTION.toLowerCase().includes(u));

// ---------- Risks ----------
const risks = parseCsv(RISKS_CSV);

// ---------- Tasks ----------
const tasks = parseCsv(TASKS_CSV).map((t) => {
  const due = toDate(t.due_date);
  return { ...t, days_until_due: daysBetween(asOf, due) };
});
const open = (t) => t.status !== 'Done';

const statusCounts = Object.fromEntries(STATUSES.map((s) => [s, tasks.filter((t) => t.status === s).length]));
const unknownStatuses = tasks.filter((t) => !STATUSES.includes(t.status)).map((t) => `${t.task_id}: ${t.status}`);

const sprintNames = [...new Set(tasks.map((t) => t.sprint))]
  .sort((a, b) => Number(a.replace(/\D/g, '')) - Number(b.replace(/\D/g, '')));
const sprints = sprintNames.map((name) => {
  const ts = tasks.filter((t) => t.sprint === name);
  const dues = ts.map((t) => t.due_date).sort();
  return {
    sprint: name,
    first_due: dues[0],
    last_due: dues[dues.length - 1],
    task_count: ts.length,
    status_counts: Object.fromEntries(STATUSES.map((s) => [s, ts.filter((t) => t.status === s).length])),
    task_ids: ts.map((t) => t.task_id),
  };
});
// Current sprint = first sprint whose last due date has not passed.
const currentSprint = (sprints.find((s) => toDate(s.last_due) >= asOf) ?? sprints[sprints.length - 1]).sprint;

const brief = (t) => ({
  task_id: t.task_id, task_name: t.task_name, status: t.status, assignee: t.assignee,
  priority: t.priority, sprint: t.sprint, due_date: t.due_date, days_until_due: t.days_until_due,
});

const blocked = tasks.filter((t) => t.status === 'Blocked').map((t) => ({ ...brief(t), description: t.description }));
const overdue = tasks.filter((t) => open(t) && toDate(t.due_date) < asOf).map(brief);
const dueSoon = tasks.filter((t) => open(t) && t.status !== 'Blocked'
  && toDate(t.due_date) >= asOf && toDate(t.due_date) <= dueSoonEnd).map(brief);

const workload = Object.entries(countBy(tasks.filter(open), 'assignee'))
  .map(([assignee, open_tasks]) => ({
    assignee,
    open_tasks,
    open_high_priority: tasks.filter((t) => open(t) && t.assignee === assignee && t.priority === 'High').length,
    in_progress: tasks.filter((t) => t.status === 'In Progress' && t.assignee === assignee).map((t) => t.task_id),
  }))
  .sort((a, b) => b.open_tasks - a.open_tasks);

const currentWeek = Math.floor(daysBetween(projectStart, asOf) / 7) + 1;
const currentPhase = timeline.find((p) => p.schedule_status === 'Current') ?? null;

const facts = {
  as_of_date: fmt(asOf),
  project_start_date: fmt(projectStart),
  current_week: currentWeek,
  total_weeks: Math.max(...timeline.map((p) => p.end_week)),
  current_phase: currentPhase ? `Phase ${currentPhase.phase}: ${currentPhase.phase_name}` : 'None (outside timeline)',
  current_sprint: currentSprint,
  total_tasks: tasks.length,
  status_counts: statusCounts,
  completion_pct: Math.round((statusCounts.Done / tasks.length) * 100),
  blocked_tasks: blocked,
  overdue_tasks: overdue,
  due_soon_tasks: dueSoon,
  due_soon_window: `${fmt(asOf)} to ${fmt(dueSoonEnd)}`,
  upcoming_milestones: milestones.filter((m) => m.days_from_as_of >= 0 && toDate(m.due_date) <= upcomingEnd),
  upcoming_window: `${fmt(asOf)} to ${fmt(upcomingEnd)}`,
  next_milestones_after_window: milestones.filter((m) => toDate(m.due_date) > upcomingEnd).slice(0, 2),
  sprints,
  workload,
  risk_count: risks.length,
  risk_categories: risks.map((r) => `${r.risk_id} ${r.category}`),
  data_warnings: unknownStatuses.map((s) => `Unrecognised task status: ${s}`),
};

return [{
  json: {
    project: { name: PROJECT_NAME, description: PROJECT_DESCRIPTION.trim(), outcome_phrases: outcomePhrases, use_cases: USE_CASES },
    timeline,
    milestones,
    risks,
    tasks,
    facts,
  },
}];

// Baseline test dataset (eval_mira_inputs.txt) with machine-checkable expectations.
// Emits one item per test listed in RUN – or, when started from the Chat Trigger, the chat message.

const incoming = $input.first()?.json ?? {};
if (incoming.chatInput) {
  return [{ json: { test_id: 'chat', query: incoming.chatInput, session_id: incoming.sessionId ?? null, checks: [] } }];
}

const RUN = ["T5", "T6", "T10"];
const WITH_ROUTE = false; // full Mira workflow: also check the Orchestrator's route
const JUDGE_MATERIAL_MAX = null; // with the Fact-Check Judge: advisory max material claims (null = no judge)

// Check types: status (value or list of accepted values) | judge_material_max | judge_min | phase_count | field (output field equals value) | grounded_min |
// mentions_all / mentions_any / not_mentions (case-insensitive, in rendered output)
// route: the agent the Orchestrator should pick (checked only when WITH_ROUTE).
const TESTS = [
  { test_id: 'T1', query: 'Generate a project plan for the AI Adoption Project at ABCDE Ltd. Use the provided project description.', route: 'planner',
    checks: [{ type: 'status', value: 'PLAN' }, { type: 'phase_count', value: 8 }, { type: 'grounded_min', value: 0.9 }] },
  { test_id: 'T2', query: 'Generate a project plan for: "We want to build a chatbot."', route: 'clarifier',
    checks: [{ type: 'status', value: 'NEEDS_CLARIFICATION' }, { type: 'mentions_all', value: ['scope', 'timeline', 'team'] }] },
  { test_id: 'T3', query: 'Generate a risk assessment for the AI Adoption Project at ABCDE Ltd. Use the provided project description.', route: 'risk',
    checks: [{ type: 'status', value: 'ASSESSMENT' }, { type: 'field', field: 'risk_count', value: 10 }, { type: 'grounded_min', value: 0.9 },
      { type: 'field', field: 'review_issue_count', value: 0 },
      { type: 'mentions_any', value: ['logistics', 'route', 'forecast', 'delivery', 'inventory'] }] },
  { test_id: 'T4', query: 'Generate a risk assessment for: "New project starting soon."', route: 'clarifier',
    checks: [{ type: 'status', value: 'NEEDS_CLARIFICATION' }, { type: 'mentions_all', value: ['scope', 'timeline'] },
      { type: 'not_mentions', value: ['R01', 'R02', 'Data Quality', 'Likelihood'] }] },
  { test_id: 'T5', query: 'Generate a weekly status report using the sample task board data for Sprint 3.', route: 'status',
    checks: [{ type: 'status', value: 'REPORT' }, { type: 'field', field: 'scope', value: 'Sprint 3' },
      { type: 'field', field: 'counts', value: 'Done 0 · In Progress 2 · Blocked 0 · To Do 2' },
      { type: 'mentions_all', value: ['Shortlist AI use cases', 'Define success criteria for each use case', 'Vendor evaluation for ML platform', 'Legal review of data usage'] },
      { type: 'grounded_min', value: 0.9 }] },
  { test_id: 'T6', query: 'Generate a weekly status report for: "Things are going fine."', route: 'clarifier',
    checks: [{ type: 'status', value: ['NO_DATA', 'NEEDS_CLARIFICATION'] }, { type: 'mentions_all', value: ['no task data'] },
      { type: 'not_mentions', value: ['%', 'T0'] }] },
  { test_id: 'T7', query: 'What are the top 3 risks for the ABCDE Ltd project based on the risk data?', route: 'risk',
    checks: [{ type: 'status', value: 'TOP_RISKS' }, { type: 'field', field: 'risk_count', value: 3 },
      { type: 'field', field: 'assessed_count', value: 10 }, { type: 'grounded_min', value: 0.9 },
      { type: 'field', field: 'review_issue_count', value: 0 }] },
  { test_id: 'T8', query: 'Which tasks are blocked or at risk of missing their deadline based on the task board?', route: 'milestone',
    checks: [{ type: 'status', value: 'ALERTS' }, { type: 'field', field: 'blocked', value: 'T024' }, { type: 'field', field: 'overdue', value: 'T006' },
      { type: 'mentions_all', value: ['T024', 'Security review of AI infrastructure', 'T006'] }, { type: 'grounded_min', value: 0.9 }] },
  { test_id: 'T9', query: 'Generate a project plan for a 2-week project with no details provided.', route: 'clarifier',
    checks: [{ type: 'status', value: 'NEEDS_CLARIFICATION' }, { type: 'mentions_all', value: ['scope', 'goal', 'deliverable'] }] },
  { test_id: 'T10', query: 'Summarize the current project status: how many tasks are done, in progress, and to do?', route: 'status',
    checks: [{ type: 'status', value: 'REPORT' }, { type: 'field', field: 'scope', value: 'Whole project' },
      { type: 'field', field: 'counts', value: 'Done 5 · In Progress 3 · Blocked 1 · To Do 16' }, { type: 'grounded_min', value: 0.9 }] },
  { test_id: 'T11', query: 'What milestones are coming up in the next 2 weeks based on the timeline?', route: 'milestone',
    checks: [{ type: 'status', value: 'ALERTS' }, { type: 'field', field: 'upcoming_count', value: 2 },
      { type: 'mentions_all', value: ['Current systems audit report', 'Gap analysis report'] }, { type: 'grounded_min', value: 0.9 }] },
  { test_id: 'T12', query: 'Generate a stakeholder update email summarizing Sprint 2 progress.', route: 'comms',
    checks: [{ type: 'status', value: 'EMAIL' }, { type: 'field', field: 'scope', value: 'Sprint 2' },
      { type: 'mentions_all', value: ['Audit existing data infrastructure', 'Map current logistics workflows', 'Identify data gaps'] },
      { type: 'not_mentions', value: ['Shortlist AI use cases', 'Legal review of data usage', 'Security review', 'Vendor evaluation', 'T007', 'T024', 'T025'] },
      { type: 'grounded_min', value: 0.9 }] },
  // Extra robustness case (not in the baseline dataset).
  { test_id: 'X1', query: 'What is the weather in Paris tomorrow?', route: 'fallback',
    checks: [{ type: 'status', value: 'OUT_OF_SCOPE' }] },
];

return TESTS.filter((t) => RUN.includes(t.test_id)).map(({ route, ...t }) => ({
  json: {
    ...t,
    checks: [
      ...(WITH_ROUTE && route ? [{ type: 'field', field: 'route', value: route }] : []),
      ...t.checks,
      ...(JUDGE_MATERIAL_MAX !== null ? [{ type: 'judge_material_max', value: JUDGE_MATERIAL_MAX, advisory: true }] : []),
    ],
  },
}));

// Status Reporter – resolves the report scope (a sprint or the whole project) in code, computes
// every number for that scope, and builds the OpenAI request. The model only writes the narrative
// and may cite only task IDs that are in scope (enum-constrained per request).

const cfg = $('Config').first().json;
const kb = $('Knowledge Base').first().json;
const f = kb.facts;
const STATUSES = ['Done', 'In Progress', 'Blocked', 'To Do'];

const SYSTEM_PROMPT = `ROLE
You are the Status Reporter inside Mira, a project intelligence assistant for PMs/TPMs at Nexora. You write the narrative of a weekly status report from task-board facts that have already been computed for you, and you refuse to report when there is no task data.

INPUT
- USER REQUEST: what the PM asked for.
- TASK DATA (optional): <scope> (what the report covers), <facts> (counts and completion already computed), <tasks_in_scope>, and <context> (carried-over, blocked and due-soon tasks, upcoming milestones). If TASK DATA is absent, the only information you have is the USER REQUEST text.

DECISION – choose exactly one status
1. TASK DATA is absent → status "NO_DATA". A sentence like "things are going fine" is not task data. Never produce statuses, counts, percentages or task names.
2. TASK DATA is present → status "REPORT".

RULES FOR A REPORT (hallucination guardrails)
- The counts, completion percentage, task tables and RAG status are rendered by code. Do not restate a number unless it appears in <facts>; never estimate or round progress.
- Only call a task overdue, blocked or due soon if <facts> or its Flags say so. A Done task is never overdue. Never generalise ("all tasks are overdue") – name the tasks.
- The only milestones are those listed under "Upcoming milestones" in <context>. A task is not a milestone – never invent one (e.g. "security review milestone").
- Refer to tasks by ID and name exactly as given (e.g. "T007 Shortlist AI use cases"). Never mention a task that is not in TASK DATA.
- headline: one sentence capturing the state of the scope (e.g. what is on track and what needs attention).
- summary: 2–3 sentences for a PM audience.
- highlights: progress worth reporting (done or advancing tasks). Each item cites the task_ids it is about.
- concerns: overdue, blocked or due-soon work and why it matters (link to upcoming milestones where relevant). Each item cites task_ids.
- next_week_focus: the 2–4 most important things to move next, each citing task_ids.
- decisions_needed: escalations or decisions the PM should raise (e.g. unblocking a blocked task). Empty array if none.

RULES FOR NO_DATA
- Set report to null.
- message: one sentence stating that no task data is available, so no status can be reported.
- what_to_provide: the information needed – e.g. task list with statuses, owners, due dates, sprint or reporting period, blockers, and milestones.

OUTPUT
Return JSON matching the provided schema. Unused branch must be null.`;

// The Orchestrator decides this (uses_project_on_file); the regex is the fallback for the standalone step workflows.
const usesTaskBoard = (q) => /task board|task data|tasks|sprint\s*\d|project status|ABCDE|AI Adoption/i.test(q);

const sprintNo = (s) => Number(String(s).replace(/\D/g, ''));
function resolveScope(q, sprint) {
  if (sprint) return { type: 'sprint', sprint: `Sprint ${sprint}` };
  const m = q.match(/sprint\s*(\d+)/i);
  if (m) return { type: 'sprint', sprint: `Sprint ${m[1]}` };
  if (/this sprint|current sprint|weekly/i.test(q)) return { type: 'sprint', sprint: f.current_sprint };
  return { type: 'project', sprint: null };
}

const counts = (ts) => Object.fromEntries(STATUSES.map((s) => [s, ts.filter((t) => t.status === s).length]));
const overdueIds = new Set(f.overdue_tasks.map((t) => t.task_id));
const line = (t) => `${t.task_id} | ${t.task_name} | ${t.status} | ${t.assignee} | ${t.priority} | ${t.sprint} | due ${t.due_date} (${t.days_until_due >= 0 ? `in ${t.days_until_due}d` : `${-t.days_until_due}d late`})${overdueIds.has(t.task_id) ? ' | OVERDUE' : ''} | ${t.description}`;

// Every number the report may contain is computed here.
function buildScope(scope) {
  const inScope = scope.type === 'sprint' ? kb.tasks.filter((t) => t.sprint === scope.sprint) : kb.tasks;
  const c = counts(inScope);
  const carriedOver = scope.type === 'sprint'
    ? kb.tasks.filter((t) => t.status !== 'Done' && sprintNo(t.sprint) < sprintNo(scope.sprint)) : [];
  const ids = new Set(inScope.map((t) => t.task_id));
  const outside = (ts) => ts.filter((t) => !ids.has(t.task_id));
  const context = {
    carried_over: carriedOver,
    blocked_elsewhere: outside(kb.tasks.filter((t) => t.status === 'Blocked')),
    due_soon_elsewhere: outside(kb.tasks.filter((t) => f.due_soon_tasks.some((d) => d.task_id === t.task_id))),
  };
  const allowed = [...new Set([...inScope, ...context.carried_over, ...context.blocked_elsewhere, ...context.due_soon_elsewhere].map((t) => t.task_id))];
  const flagged = (pred) => inScope.filter(pred).map((t) => t.task_id);
  return {
    label: scope.type === 'sprint' ? scope.sprint : 'Whole project',
    type: scope.type,
    sprint: scope.sprint,
    task_ids: inScope.map((t) => t.task_id),
    status_counts: c,
    total: inScope.length,
    completion_pct: inScope.length ? Math.round((c.Done / inScope.length) * 100) : 0,
    overdue_ids: flagged((t) => overdueIds.has(t.task_id)),
    blocked_ids: flagged((t) => t.status === 'Blocked'),
    due_soon_ids: flagged((t) => f.due_soon_tasks.some((d) => d.task_id === t.task_id)),
    context_ids: {
      carried_over: context.carried_over.map((t) => t.task_id),
      blocked_elsewhere: context.blocked_elsewhere.map((t) => t.task_id),
      due_soon_elsewhere: context.due_soon_elsewhere.map((t) => t.task_id),
    },
    allowed_task_ids: allowed,
    found: inScope.length > 0,
  };
}

const flags = (ids) => (ids.length ? `${ids.length} (${ids.join(', ')})` : '0');

function taskDataBlock(s) {
  const byId = new Map(kb.tasks.map((t) => [t.task_id, t]));
  const rows = (ids) => (ids.length ? ids.map((id) => line(byId.get(id))).join('\n') : 'none');
  // A milestone's linked tasks are those due inside its phase (same rule as the Milestone Tracker),
  // so any task→milestone dependency the narrative states is backed by data.
  const phaseOf = new Map(kb.timeline.map((p) => [p.phase, p]));
  const linked = (m) => kb.tasks.filter((t) => t.due_date >= phaseOf.get(m.phase).start_date && t.due_date <= phaseOf.get(m.phase).end_date)
    .map((t) => `${t.task_id} ${t.status}`).join(', ') || 'none';
  const ms = f.upcoming_milestones.map((m) => `\n- ${m.milestone} (Phase ${m.phase}, due ${m.due_date}; linked tasks: ${linked(m)})`).join('') || ' none';
  return `TASK DATA – ${kb.project.name}\n` +
    `<scope>\n${s.label} · as of ${f.as_of_date} (week ${f.current_week} of ${f.total_weeks}, ${f.current_phase}; current sprint ${f.current_sprint})\n</scope>\n` +
    `<facts>\nTasks in scope: ${s.total}\n${STATUSES.map((st) => `${st}: ${s.status_counts[st]}`).join('\n')}\nCompletion: ${s.completion_pct}%\n` +
    `Overdue in scope: ${flags(s.overdue_ids)}\nBlocked in scope: ${flags(s.blocked_ids)}\n` +
    `Due within ${cfg.dueSoonDays} days in scope: ${flags(s.due_soon_ids)}\n</facts>\n` +
    `<tasks_in_scope>\nTask | Name | Status | Assignee | Priority | Sprint | Due | Flags | Description\n${rows(s.task_ids)}\n</tasks_in_scope>\n` +
    `<context>\nCarried over from earlier sprints (not done): \n${rows(s.context_ids.carried_over)}\n` +
    `Blocked outside scope: \n${rows(s.context_ids.blocked_elsewhere)}\n` +
    `Due within ${cfg.dueSoonDays} days outside scope: \n${rows(s.context_ids.due_soon_elsewhere)}\n` +
    `Upcoming milestones (${f.upcoming_window}) – the ONLY milestones; use their exact names:${ms}\n</context>`;
}

function responseFormat(allowedIds) {
  const strings = { type: 'array', items: { type: 'string' } };
  const cited = {
    type: 'array',
    items: {
      type: 'object', additionalProperties: false, required: ['text', 'task_ids'],
      properties: { text: { type: 'string' }, task_ids: { type: 'array', items: { type: 'string', enum: allowedIds } } },
    },
  };
  return {
    type: 'json_schema',
    json_schema: {
      name: 'status_output',
      strict: true,
      schema: {
        type: 'object', additionalProperties: false, required: ['status', 'no_data', 'report'],
        properties: {
          status: { type: 'string', enum: ['REPORT', 'NO_DATA'] },
          no_data: {
            anyOf: [{ type: 'null' }, {
              type: 'object', additionalProperties: false, required: ['message', 'what_to_provide'],
              properties: { message: { type: 'string' }, what_to_provide: strings },
            }],
          },
          report: {
            anyOf: [{ type: 'null' }, {
              type: 'object', additionalProperties: false,
              required: ['headline', 'summary', 'highlights', 'concerns', 'next_week_focus', 'decisions_needed'],
              properties: {
                headline: { type: 'string' }, summary: { type: 'string' },
                highlights: cited, concerns: cited, next_week_focus: cited, decisions_needed: cited,
              },
            }],
          },
        },
      },
    },
  };
}

return $input.all().map(({ json: req }) => {
  const scope = (req.uses_project_on_file ?? usesTaskBoard(req.query)) ? buildScope(resolveScope(req.query, req.sprint)) : null;
  const hasData = Boolean(scope?.found);
  const userContent = `USER REQUEST:\n${req.query}\n\n` +
    (hasData ? taskDataBlock(scope) : 'TASK DATA: none provided.');
  const messages = [
    { role: 'system', content: SYSTEM_PROMPT },
    { role: 'user', content: userContent },
  ];
  return {
    json: {
      ...req,
      agent: 'Status Reporter',
      uses_project_data: hasData,
      scope,
      started_at: new Date().toISOString(),
      openaiRequest: {
        model: cfg.model,
        temperature: Number(cfg.temperature),
        max_tokens: Number(cfg.maxTokens),
        response_format: responseFormat(hasData ? scope.allowed_task_ids : kb.tasks.map((t) => t.task_id)),
        messages,
      },
    },
  };
});

// Status Reporter – parses the model narrative, verifies every task ID and number in it against
// the computed facts, renders the report (counts, tables and RAG come from code), and describes
// the LangSmith trace for this request.

const kb = $('Knowledge Base').first().json;
const cfg = $('Config').first().json;
const requests = $('Status Reporter: Build Prompt').all();
const f = kb.facts;
const STATUSES = ['Done', 'In Progress', 'Blocked', 'To Do'];

const byId = new Map(kb.tasks.map((t) => [t.task_id, t]));
const overdueIds = new Set(f.overdue_tasks.map((t) => t.task_id));
const cell = (s) => String(s ?? '').replace(/\|/g, '/').replace(/\n/g, ' ');
const list = (items) => (items.length ? items.map((x) => `- ${x}`).join('\n') : '- _None._');
const timing = (t) => (t.status === 'Done' ? 'Done'
  : t.status === 'Blocked' ? `⛔ Blocked · due in ${t.days_until_due}d`
  : t.days_until_due < 0 ? `⚠ ${-t.days_until_due}d overdue` : t.days_until_due === 0 ? 'Due today' : `Due in ${t.days_until_due}d`);

// RAG from fixed rules, so the overall status never depends on the model's tone.
function rag(scope) {
  const watched = [...scope.task_ids, ...scope.context_ids.carried_over].map((id) => byId.get(id));
  const overdue = watched.filter((t) => overdueIds.has(t.task_id));
  const blocked = watched.filter((t) => t.status === 'Blocked');
  const reasons = [];
  let level = 'Green';
  const lateHigh = overdue.filter((t) => t.priority === 'High' && -t.days_until_due > 7);
  const blockedSoon = blocked.filter((t) => t.days_until_due <= Number(cfg.dueSoonDays));
  if (lateHigh.length || blockedSoon.length) {
    level = 'Red';
    lateHigh.forEach((t) => reasons.push(`${t.task_id} is high priority and more than 7 days overdue`));
    blockedSoon.forEach((t) => reasons.push(`${t.task_id} is blocked and due within ${cfg.dueSoonDays} days`));
  } else if (overdue.length || blocked.length) {
    level = 'Amber';
    overdue.forEach((t) => reasons.push(`${t.task_id} ${t.task_name} is ${-t.days_until_due}d overdue`));
    blocked.forEach((t) => reasons.push(`${t.task_id} ${t.task_name} is blocked (due ${t.due_date})`));
  } else reasons.push('no overdue or blocked tasks');
  return { level, reasons };
}
const RAG_ICON = { Green: '🟢', Amber: '🟠', Red: '🔴' };

// Numbers the narrative may use: computed counts/percentages, task timings and numbers that
// appear in the source task text (e.g. KPIs "15%", "3 distribution centers").
function allowedNumbers(scope) {
  const nums = new Set([scope.total, f.total_tasks, f.current_week, f.total_weeks,
    ...Object.values(scope.status_counts), ...Object.values(f.status_counts),
    scope.context_ids.carried_over.length, scope.context_ids.blocked_elsewhere.length,
    scope.context_ids.due_soon_elsewhere.length, f.upcoming_milestones.length,
    scope.overdue_ids.length, scope.blocked_ids.length, scope.due_soon_ids.length,
    f.overdue_tasks.length, f.blocked_tasks.length, f.due_soon_tasks.length,
    Number(cfg.dueSoonDays), Number(cfg.upcomingWindowDays)]);
  const pcts = new Set([scope.completion_pct, f.completion_pct]);
  for (const id of scope.allowed_task_ids) {
    const t = byId.get(id);
    nums.add(Math.abs(t.days_until_due));
    for (const m of `${t.task_name} ${t.description}`.matchAll(/(\d+)(%?)/g)) (m[2] ? pcts : nums).add(Number(m[1]));
  }
  for (const m of kb.project.description.matchAll(/(\d+)%/g)) pcts.add(Number(m[1]));
  const dates = new Set([f.as_of_date, ...scope.allowed_task_ids.map((id) => byId.get(id).due_date),
    ...f.upcoming_milestones.map((m) => m.due_date)]);
  return { nums, pcts, dates };
}

// Dates in the narrative ("2026-04-26", "April 26, 2026", "26 April") must be real dates from the data.
const MONTHS = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'];
const MONTH = '(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\\.?';
const DATE_PATTERNS = [
  [/\b(\d{4})-(\d{2})-(\d{2})\b/g, (m) => [m[1], m[2], m[3]]],
  [new RegExp(`\\b${MONTH}\\s+(\\d{1,2})(?:st|nd|rd|th)?(?:,?\\s+(\\d{4}))?`, 'gi'), (m) => [m[3], MONTHS.indexOf(m[1].toLowerCase()) + 1, m[2]]],
  [new RegExp(`\\b(\\d{1,2})(?:st|nd|rd|th)?\\s+${MONTH}(?:,?\\s+(\\d{4}))?`, 'gi'), (m) => [m[3], MONTHS.indexOf(m[2].toLowerCase()) + 1, m[1]]],
];
function extractDates(text) {
  const found = [];
  let rest = text;
  for (const [re, parts] of DATE_PATTERNS) {
    rest = rest.replace(re, (...m) => {
      const [y, mo, d] = parts(m);
      found.push({ raw: m[0], iso: `${y ?? f.as_of_date.slice(0, 4)}-${String(mo).padStart(2, '0')}-${String(d).padStart(2, '0')}` });
      return ' ';
    });
  }
  return { found, rest };
}

// "X milestone" phrases must name a real milestone: the word right before "milestone" must occur in a
// milestone name, or be generic ("upcoming milestones", "the Phase 2 milestones").
const milestoneWords = new Set(kb.milestones.flatMap((m) => m.milestone.toLowerCase().split(/[^a-z0-9]+/)));
const GENERIC = new Set(['the', 'a', 'an', 'these', 'those', 'both', 'two', 'its', 'their', 'our', 'upcoming', 'next', 'key',
  'current', 'phase', 'project', 'related', 'linked', 'this', 'that', 'any', 'other', 'and', 'of', 'for', 'to', 'two', 'all']);
function inventedMilestones(text) {
  return [...text.matchAll(/((?:[A-Za-z0-9'-]+\s+){1,3})milestones?\b/gi)]
    .filter((m) => {
      const head = m[1].toLowerCase().trim().split(/\s+/).pop().replace(/'s$/, '');
      return !GENERIC.has(head) && !milestoneWords.has(head) && !/^\d+$/.test(head);
    })
    .map((m) => m[0].trim());
}

function groundingCheck(report, scope) {
  const allowed = new Set(scope.allowed_task_ids);
  const { nums, pcts, dates } = allowedNumbers(scope);
  const items = [
    { where: 'headline', text: report.headline, task_ids: [] },
    { where: 'summary', text: report.summary, task_ids: [] },
    ...['highlights', 'concerns', 'next_week_focus', 'decisions_needed']
      .flatMap((k) => report[k].map((x, i) => ({ where: `${k}[${i + 1}]`, ...x }))),
  ];
  const issues = [];
  let grounded = 0;
  for (const it of items) {
    const problems = [];
    const ids = [...new Set([...(it.text.match(/\bT\d{3}\b/g) ?? []), ...it.task_ids])];
    const outOfScope = ids.filter((id) => !allowed.has(id));
    if (outOfScope.length) problems.push(`task not in scope: ${outOfScope.join(', ')}`);
    inventedMilestones(it.text).forEach((m) => problems.push(`no such milestone: “${m}”`));
    const { found, rest } = extractDates(it.text);
    found.filter((d) => !dates.has(d.iso)).forEach((d) => problems.push(`unsupported date “${d.raw}”`));
    const stripped = rest.replace(/\bT\d{3}\b/g, ' ').replace(/\b(sprint|phase|week|q)\s*\d+/gi, ' ');
    for (const m of stripped.matchAll(/(\d+(?:\.\d+)?)\s*(%|percent)?/g)) {
      const n = Number(m[1]);
      if (m[2] ? !pcts.has(n) : !nums.has(n)) problems.push(`unsupported ${m[2] ? 'percentage' : 'number'} “${m[0].trim()}”`);
    }
    if (problems.length) issues.push(`${it.where}: ${problems.join(', ')}`);
    else grounded++;
  }
  return { checked: items.length, grounded, score: items.length ? grounded / items.length : 1, issues };
}

function taskTable(ids) {
  return ['| ID | Task | Owner | Priority | Sprint | Due | Timing |', '|---|---|---|---|---|---|---|',
    ...ids.map((id) => byId.get(id)).map((t) =>
      `| ${t.task_id} | ${cell(t.task_name)} | ${t.assignee} | ${t.priority} | ${t.sprint} | ${t.due_date} | ${timing(t)} |`)].join('\n');
}

const citedList = (items) => (items.length
  ? items.map((x) => `- ${x.text}${x.task_ids.length ? ` _(${x.task_ids.join(', ')})_` : ''}`).join('\n')
  : '- _None._');

function renderReport(report, scope, r, grounding) {
  const c = scope.status_counts;
  const progress = ['| Status | Tasks |', '|---|---|', ...STATUSES.map((s) => `| ${s} | ${c[s]} |`), `| **Total** | **${scope.total}** |`].join('\n');
  const byStatus = STATUSES.filter((s) => c[s] > 0).map((s) =>
    `### ${s} (${c[s]})\n\n${taskTable(scope.task_ids.filter((id) => byId.get(id).status === s))}`);
  const ctx = scope.context_ids;
  const context = [
    ctx.carried_over.length ? `**Carried over from earlier sprints (not done)**\n\n${taskTable(ctx.carried_over)}` : null,
    ctx.blocked_elsewhere.length ? `**Blocked outside this scope**\n\n${taskTable(ctx.blocked_elsewhere)}` : null,
    ctx.due_soon_elsewhere.length ? `**Due within ${cfg.dueSoonDays} days outside this scope**\n\n${taskTable(ctx.due_soon_elsewhere)}` : null,
  ].filter(Boolean);
  return [
    `# Weekly Status Report — ${scope.label}`,
    `_Generated by Mira · as of ${f.as_of_date} (week ${f.current_week} of ${f.total_weeks}, ${f.current_phase}) · Source: sample_task_board.csv_`,
    `**Overall status: ${RAG_ICON[r.level]} ${r.level}** — ${r.reasons.join('; ')}`,
    `**${report.headline}**`,
    '## Summary', report.summary,
    '## Progress',
    `${progress}\n\nCompletion: **${scope.completion_pct}%** (${c.Done} of ${scope.total} done)` +
      (scope.type === 'sprint' ? ` · Whole project: ${f.completion_pct}% (${f.status_counts.Done} of ${f.total_tasks} done)` : ''),
    '## Tasks by status', ...byStatus,
    ...(context.length ? ['## Watch list', ...context] : []),
    '## Highlights', citedList(report.highlights),
    '## Concerns & blockers', citedList(report.concerns),
    '## Focus for next week', citedList(report.next_week_focus),
    '## Decisions / escalations needed', citedList(report.decisions_needed),
    '---',
    `Grounding check: ${grounding.grounded}/${grounding.checked} narrative items verified (task IDs in scope, numbers match the task board)` +
      (grounding.issues.length ? `\n${grounding.issues.map((i) => `- ⚠ ${i}`).join('\n')}` : ' ✅'),
  ].join('\n\n');
}

function renderNoData(nd, req) {
  const notFound = req.scope && !req.scope.found ? `${req.scope.label} has no tasks on the task board. ` : '';
  return [
    '## No task data available',
    `${notFound}I can't produce a status report from the request alone – there are no task statuses, owners or due dates to report on.`,
    nd.message,
    '**To generate the report, please provide**', list(nd.what_to_provide),
    '_No task statuses, counts or progress percentages were generated._',
  ].join('\n\n');
}

return $input.all().map((item, i) => {
  const req = requests[i].json;
  const body = item.json.body ?? item.json;
  const headers = item.json.headers ?? {};
  const finishedAt = new Date().toISOString();
  const content = body.choices?.[0]?.message?.content ?? '';

  let output = null, parseError = null;
  try { output = JSON.parse(content); } catch (e) { parseError = e.message; }

  let markdown, grounding = null, r = null;
  const status = output?.status ?? 'ERROR';
  const scope = req.scope;
  if (!output) {
    markdown = `⚠ Status Reporter returned unparseable output (${parseError}).\n\n${content}`;
  } else if (status === 'REPORT' && output.report && scope?.found) {
    grounding = groundingCheck(output.report, scope);
    r = rag(scope);
    markdown = renderReport(output.report, scope, r, grounding);
  } else {
    markdown = renderNoData(output.no_data ?? { message: 'No task data was provided.', what_to_provide: [] }, req);
  }

  // Model latency from OpenAI's header gives accurate per-call timing even when items run in sequence.
  const latencyMs = Number(headers['openai-processing-ms']) || (Date.parse(finishedAt) - Date.parse(req.started_at));
  const llmEnd = new Date(Date.parse(req.started_at) + latencyMs).toISOString();
  const usage = body.usage ?? {};
  const counts = grounding ? STATUSES.map((s) => `${s} ${scope.status_counts[s]}`).join(' · ') : null;

  return {
    json: {
      test_id: req.test_id,
      query: req.query,
      checks: req.checks,
      agent: req.agent,
      status,
      uses_project_data: req.uses_project_data,
      scope: grounding ? scope.label : null,
      counts,
      rag: r?.level ?? null,
      grounding,
      markdown,
      usage: { input_tokens: usage.prompt_tokens ?? 0, output_tokens: usage.completion_tokens ?? 0, total_tokens: usage.total_tokens ?? 0 },
      trace: {
        name: 'Mira',
        start_time: req.started_at,
        end_time: finishedAt,
        inputs: { query: req.query },
        outputs: { status, response: markdown },
        tags: ['mira', 'status', req.test_id].filter(Boolean),
        metadata: { test_id: req.test_id, agent: req.agent, status, scope: scope?.label ?? null, uses_project_data: req.uses_project_data, groundedness: grounding?.score ?? null, as_of_date: f.as_of_date },
        children: [
          {
            name: req.agent,
            run_type: 'llm',
            start_time: req.started_at,
            end_time: llmEnd,
            inputs: { messages: req.openaiRequest.messages },
            outputs: body,
            model: req.openaiRequest.model,
            temperature: req.openaiRequest.temperature,
          },
          {
            name: 'Grounding Check',
            run_type: 'chain',
            start_time: llmEnd,
            end_time: finishedAt,
            inputs: { status, scope: scope?.label ?? null },
            outputs: grounding ? { ...grounding, rag: r, counts } : { skipped: 'no report generated' },
          },
        ],
      },
    },
  };
});

// Reusable: converts each item's `trace` descriptor into a LangSmith /runs/batch payload.
// Descriptor: { name, start_time, end_time, inputs, outputs, tags, metadata,
//               children: [{ name, run_type, start_time, end_time, inputs, outputs, model?, temperature? }] }

const cfg = $('Config').first().json;

// UUID v7 (time-ordered), which LangSmith expects for run IDs.
function uuidv7(ms) {
  const r = (n) => Array.from({ length: n }, () => Math.floor(Math.random() * 16).toString(16)).join('');
  const ts = ms.toString(16).padStart(12, '0');
  const variant = '89ab'[Math.floor(Math.random() * 4)];
  return `${ts.slice(0, 8)}-${ts.slice(8, 12)}-7${r(3)}-${variant}${r(3)}-${r(12)}`;
}

// LangSmith dotted_order segment: YYYYMMDDTHHMMSSffffffZ + run id
const dottedTs = (iso) => iso.replace(/[-:]/g, '').replace('.', '').replace('Z', '000Z');

function usageMetadata(outputs) {
  const u = outputs?.usage ?? {};
  return { input_tokens: u.prompt_tokens ?? 0, output_tokens: u.completion_tokens ?? 0, total_tokens: u.total_tokens ?? 0 };
}

return $input.all().map(({ json }) => {
  const t = json.trace;
  const rootStart = Date.parse(t.start_time);
  const traceId = uuidv7(rootStart);
  const rootDotted = dottedTs(t.start_time) + traceId;

  const root = {
    id: traceId,
    trace_id: traceId,
    dotted_order: rootDotted,
    name: t.name,
    run_type: 'chain',
    inputs: t.inputs,
    outputs: t.outputs,
    start_time: t.start_time,
    end_time: t.end_time,
    session_name: cfg.langsmithProject,
    tags: t.tags,
    extra: { metadata: { ...t.metadata, n8n_execution_id: $execution.id } },
  };

  // Children start strictly after the root (+1 ms each) so dotted_order stays monotonic.
  const children = (t.children ?? []).map((c, idx) => {
    const startMs = Math.max(Date.parse(c.start_time), rootStart + idx + 1);
    const start = new Date(startMs).toISOString();
    const end = new Date(Math.max(Date.parse(c.end_time), startMs)).toISOString();
    const id = uuidv7(startMs);
    const run = {
      id,
      trace_id: traceId,
      parent_run_id: traceId,
      dotted_order: `${rootDotted}.${dottedTs(start)}${id}`,
      name: c.name,
      run_type: c.run_type,
      inputs: c.inputs,
      outputs: c.outputs,
      start_time: start,
      end_time: end,
      session_name: cfg.langsmithProject,
    };
    if (c.run_type === 'llm') {
      run.outputs = { ...c.outputs, usage_metadata: usageMetadata(c.outputs) };
      run.extra = {
        metadata: { ls_provider: 'openai', ls_model_name: c.model, ls_model_type: 'chat', ls_temperature: c.temperature },
        invocation_params: { model: c.model, temperature: c.temperature },
      };
    }
    return run;
  });

  return { json: { test_id: json.test_id, trace_id: traceId, batch: { post: [root, ...children] } } };
});

// Scores each agent output against its test's expectations (see Test Cases node).

const outputs = $('Status Reporter: Format Output').all().map((i) => i.json);
const traceIds = $('LangSmith: Build Trace').all().map((i) => i.json.trace_id);

function evaluate(check, out) {
  const text = out.markdown.toLowerCase();
  switch (check.type) {
    case 'status':
      return [[].concat(check.value).includes(out.status), `status ${out.status}`];
    case 'phase_count':
      return [out.phase_count === check.value, `${out.phase_count} phases`];
    case 'field':
      return [out[check.field] === check.value, `${check.field} = ${JSON.stringify(out[check.field])}`];
    case 'judge_material_max': {
      if (out.judge_skipped) return [true, 'fact-check n/a'];
      const claims = out.judge?.unsupported_claims ?? [];
      const material = claims.filter((c) => c.severity === 'material').length;
      return [out.judge_score !== null && material <= check.value, `fact-check ${out.judge_score ?? '–'}/5 · ${material} material, ${claims.length - material} minor`];
    }
    case 'judge_min':
      if (out.judge_skipped) return [true, 'fact-check n/a'];
      return [(out.judge_score ?? 0) >= check.value, `fact-check ${out.judge_score ?? '–'}/5${out.unsupported_count ? ` (${out.unsupported_count} unsupported)` : ''}`];
    case 'grounded_min': {
      const score = out.grounding?.score ?? 0;
      return [score >= check.value, `groundedness ${(score * 100).toFixed(0)}%`];
    }
    case 'mentions_all': {
      const missing = check.value.filter((term) => !text.includes(term.toLowerCase()));
      return [missing.length === 0, missing.length ? `missing: ${missing.join(', ')}` : `mentions ${check.value.join(', ')}`];
    }
    case 'mentions_any': {
      const hit = check.value.filter((term) => text.includes(term.toLowerCase()));
      return [hit.length > 0, hit.length ? `mentions ${hit.join(', ')}` : `none of: ${check.value.join(', ')}`];
    }
    case 'not_mentions': {
      const found = check.value.filter((term) => text.includes(term.toLowerCase()));
      return [found.length === 0, found.length ? `should not mention: ${found.join(', ')}` : 'no forbidden terms'];
    }
    default:
      return [false, `unknown check ${check.type}`];
  }
}

return outputs.map((out, i) => {
  // Advisory checks (the LLM judge, ~50% measured precision) are shown as INFO and never decide the verdict.
  const results = (out.checks ?? []).map((c) => {
    const [pass, detail] = evaluate(c, out);
    return `${c.advisory ? 'INFO' : pass ? 'PASS' : 'FAIL'} – ${c.type}: ${detail}${c.advisory && !pass ? ' (review)' : ''}`;
  });
  const failed = results.filter((r) => r.startsWith('FAIL')).length;
  const graded = results.filter((r) => !r.startsWith('INFO')).length;
  return {
    json: {
      test_id: out.test_id,
      verdict: results.length === 0 ? 'NO CHECKS' : failed === 0 ? 'PASS' : 'FAIL',
      checks: results,
      checks_passed: graded - failed,
      checks_total: graded,
      status: out.status,
      tokens: out.usage.total_tokens,
      route: out.route,
      expected_route: (out.checks ?? []).find((c) => c.type === 'field' && c.field === 'route')?.value ?? null,
      groundedness: out.grounding?.score ?? null,
      judge_score: out.judge_score,
      judge_material: out.judge_skipped ? null : (out.judge?.unsupported_claims ?? []).filter((c) => c.severity === 'material').length,
      query: out.query,
      started_at: out.started_at_trace ?? null,
      ended_at: out.ended_at_trace ?? null,
      unsupported_claims: (out.judge?.unsupported_claims ?? []).map((c) => c.claim),
      langsmith_trace_id: traceIds[i],
      response: out.markdown,
      output: out.markdown, // shown as the reply when Mira runs from the Chat Trigger
    },
  };
});
